import React, { useState, useEffect } from "react";

function Registerpage(props) {
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [name, setName] = useState("");
  const [data, setData] = useState([]);

  useEffect(() => {
    {
      fetch("http://localhost:3000/data").then((response) =>
        response.json().then((user) => setData(user))
      );
    }
  }, []);

  function handleUsernameChange(event) {
    setUsername(event.target.value);
  }

  function handlePasswordChange(event) {
    setPassword(event.target.value);
  }

  function handleNameChnage(event) {
    setName(event.target.value);
  }

  const displayData = (event) => {
    event.preventDefault();

    data.map((value) => {
      if (value.username === username) alert("Username already exist");
    });
    let user = { name, username, password };

    if (username) {
      fetch("http://localhost:3000/data", {
        method: "POST",
        headers: {
          Accept: "application/json",
          "Content-type": "application/json",
        },
        body: JSON.stringify(user),
      }).then((response) =>
        response.json().then((result) => console.log(result))
      );

      //data.data.push({ id, name, username, password });
      alert("User added");
    }
  };

  return (
    <div className="container">
      <h1>Registration Page: </h1>
      <form className="form">
        <label className="pa label"> Name: </label>
        <input
          className="pa input"
          type="text"
          onChange={handleNameChnage}
        ></input>
        <label className="pa label">Username: </label>
        <input
          className="pa input"
          type="text"
          onChange={handleUsernameChange}
        ></input>
        <label className="pa label">Password: </label>
        <input
          className="pa input"
          type="password"
          onChange={handlePasswordChange}
        ></input>
        <button className="pa btn" type="submit" onClick={displayData}>
          Register
        </button>
        <button
          className="pa reg-btn"
          onClick={() => props.onFormSwitch("login")}
        >
          Already have a account Login here
        </button>
      </form>
    </div>
  );
}

export default Registerpage;
